package org.deposit.it;
import static org.junit.jupiter.api.Assertions.*;
import static org.deposit.it.Stage1LifecycleIT.*;
import java.util.*;
import java.nio.file.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;

/** Supervisor-executed process boundaries. Each fixture persists IDs/operations, never tokens. */
@Timeout(180)
class Stage5CrashIT {
    static final Path FIXTURE=ROOT.resolve("stage5-crash.properties");
    static void save(Properties p)throws Exception{try(var out=Files.newOutputStream(FIXTURE)){p.store(out,"Stage5 termination fixture; no credentials");}Files.copy(FIXTURE,Path.of(System.getenv("STAGE0_EVIDENCE")).resolve("stage5-crash-fixture.properties"),StandardCopyOption.REPLACE_EXISTING);}
    static Properties load()throws Exception{var p=new Properties();try(var in=Files.newInputStream(FIXTURE)){p.load(in);}return p;}
    static void setup(){connect();Stage4ProbeIT.ensureAccount();Stage5CoreIT.token=Stage3CoreIT.login();Stage5CoreIT.fixture5();}
    @Test void triggerAction()throws Exception {setup();try{String point=System.getenv("STAGE5_CRASH_POINT");assertTrue(Set.of("history-before-receipt","history-after-commit").contains(point));var context=write(Stage5CoreIT.token,Stage5CoreIT.seq());var p=new Properties();p.setProperty("point",point);p.setProperty("namespace",Stage5CoreIT.ns);p.setProperty("object",Stage5CoreIT.object);p.setProperty("operationId",(String)context.get("operationId"));p.setProperty("sequence",context.get("expectedRevision").toString());save(p);Stage4ProbeIT.arm(point,"pause");try(var pool=Executors.newSingleThreadExecutor()){var task=pool.submit(()->call("deposit.set.descriptor",m("objectId",Stage5CoreIT.object,"name","Mass","value",20L),context));Path marker=ROOT.resolve("stage4-pause.json");long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(30);while(!Files.exists(marker)&&System.nanoTime()<end)Thread.sleep(30);assertTrue(Files.exists(marker));assertTrue(Files.readString(marker).contains(point));Path helper=Path.of("..","scripts","Kill-TestOwnedJvm.ps1").toAbsolutePath().normalize();Process killer=new ProcessBuilder("powershell.exe","-NoProfile","-File",helper.toString()).redirectErrorStream(true).start();assertTrue(killer.waitFor(20,TimeUnit.SECONDS));assertEquals(0,killer.exitValue());try{task.get(20,TimeUnit.SECONDS);}catch(ExecutionException failure){assertTrue(failure.getCause() instanceof org.neo4j.driver.exceptions.Neo4jException);}Files.writeString(Path.of(System.getenv("STAGE0_EVIDENCE")).resolve("stage5-action-kill.txt"),point);}}finally{close();}}
    @Test void verifyAction()throws Exception {connect();try{var p=load();String token=Stage3CoreIT.login();Stage5CoreIT.token=token;Stage3CoreIT.select(token,p.getProperty("namespace"));Stage5CoreIT.object=p.getProperty("object");long before=Long.parseLong(p.getProperty("sequence"));boolean committed=p.getProperty("point").equals("history-after-commit");assertEquals(before+(committed?1:0),Stage5CoreIT.seq());assertEquals(committed?20L:10L,Stage5CoreIT.value());assertEquals(committed?1:0,query("MATCH (r:DepositReceipt {scope:$ns,operationId:$op}) RETURN count(r) AS n",m("ns",p.getProperty("namespace"),"op",p.getProperty("operationId"))).getFirst().get("n").asInt());var retry=write(token,before);retry.put("operationId",p.getProperty("operationId"));var request=m("objectId",p.getProperty("object"),"name","Mass","value",20L);var result=call("deposit.set.descriptor",request,retry);assertEquals(result.get("data"),call("deposit.set.descriptor",request,retry).get("data"));assertEquals(before+1,Stage5CoreIT.seq());assertEquals(1,query("MATCH (r:Revision {namespaceId:$ns,operationId:$op}) RETURN count(r) AS n",m("ns",p.getProperty("namespace"),"op",p.getProperty("operationId"))).getFirst().get("n").asInt());}finally{close();}}
    @Test void seedStartup()throws Exception {setup();try{String point=System.getenv("STAGE5_CRASH_POINT");assertTrue(Set.of("history-invalidated","history-cleanup-batch","history-before-baseline","history-after-baseline").contains(point));Stage5CoreIT.change("deposit.set.versioningType",m("mode","transient"));Stage5CoreIT.stage4();String resource=Stage4CoreIT.upload(Stage4CoreIT.ABC,"transient-history");Stage4CoreIT.descriptor("File","DResource",m("resourceId",resource));Stage5CoreIT.change("deposit.set.descriptor",m("objectId",Stage5CoreIT.object,"name","File","value",null));String geometry=Stage4CoreIT.descriptor("G","DGeometry",Stage4CoreIT.geometry("POINT Z (12 34 56)",4326L,3)).get("data").get("geometryId").asString();for(int i=0;i<140;i++)Stage5CoreIT.mass(20+i);var p=new Properties();p.setProperty("point",point);p.setProperty("namespace",Stage5CoreIT.ns);p.setProperty("object",Stage5CoreIT.object);p.setProperty("resource",resource);p.setProperty("geometry",geometry);p.setProperty("sequence",Long.toString(Stage5CoreIT.seq()));p.setProperty("oldHead",Stage5CoreIT.head());p.setProperty("namespaceUpdatedAt",Stage5CoreIT.audit(Stage5CoreIT.ns).get("updatedAt").toString());query("MATCH (l:DepositResourceLocation {id:$id}) SET l.leaseUntil=0",m("id",resource));save(p);Files.deleteIfExists(ROOT.resolve("stage5-startup-paused.txt"));Files.deleteIfExists(ROOT.resolve("stage5-startup-release.txt"));Files.writeString(ROOT.resolve("stage5-startup-arm.txt"),point+"/"+Stage5CoreIT.ns);}finally{close();}}
    @Test void verifyStartup()throws Exception {connect();try{var p=load();String token=Stage3CoreIT.login();Stage5CoreIT.token=token;Stage3CoreIT.select(token,p.getProperty("namespace"));assertEquals(Long.parseLong(p.getProperty("sequence")),Stage5CoreIT.seq());assertEquals(p.getProperty("namespaceUpdatedAt"),Stage5CoreIT.audit(p.getProperty("namespace")).get("updatedAt").toString());assertNotEquals(p.getProperty("oldHead"),Stage5CoreIT.head());assertEquals(159L,call("deposit.get.descriptor",m("objectId",p.getProperty("object"),"name","Mass"),ctx(token)).get("data").get("value").asLong());assertEquals(p.getProperty("geometry"),call("deposit.get.descriptor",m("objectId",p.getProperty("object"),"name","G"),ctx(token)).get("data").get("geometryId").asString());var revisions=query("MATCH (e:DepositHistoryEpoch {namespaceId:$ns,mode:'transient'}) RETURN count(e) AS n",m("ns",p.getProperty("namespace")));assertEquals(1,revisions.getFirst().get("n").asInt());assertEquals(0,query("MATCH (r:Revision {id:$id}) RETURN count(r) AS n",m("id",p.getProperty("oldHead"))).getFirst().get("n").asInt());error("NOT_FOUND",()->call("deposit.resource.info",m("resourceId",p.getProperty("resource")),ctx(token)));assertEquals(0,query("MATCH (:DepositSnapshot)-[r:RETAINS_RESOURCE]->(:DResource {id:$id}) RETURN count(r) AS n",m("id",p.getProperty("resource"))).getFirst().get("n").asInt());Stage4CoreIT.ns=p.getProperty("namespace");assertEquals(1L,Stage4ProbeIT.inspect().get("layers").asList(v->v.get("count").asLong()).stream().mapToLong(x->x).sum());Files.writeString(Path.of(System.getenv("STAGE0_EVIDENCE")).resolve("stage5-startup-recovered.txt"),p.getProperty("point")+"\nsequence="+Stage5CoreIT.seq());}finally{close();}}
}
